function myAtoi(s) {
  const MAX = 2 ** 31 - 1, MIN = -(2 ** 31);
  let i = 0;
  while (i < s.length && s[i] === " ") i++;          // 1. skip leading spaces
  let sign = 1;
  if (s[i] === "+" || s[i] === "-") {                // 2. an optional sign
    if (s[i] === "-") sign = -1;
    i++;
  }
  let value = 0;                                     // a JS number is exact far past 2^31
  while (i < s.length && s[i] >= "0" && s[i] <= "9") {   // 3. digits, until anything else
    value = value * 10 + (s.charCodeAt(i) - 48);
    if (value > MAX + 1) break;                      // already too big: stop reading
    i++;
  }
  return Math.max(MIN, Math.min(MAX, sign * value)); // 4. clamp into the 32-bit range
}

int myAtoi(String s) {
    int i = 0, n = s.length();
    while (i < n && s.charAt(i) == ' ') i++;     // 1. skip leading spaces
    int sign = 1;
    if (i < n && (s.charAt(i) == '+' || s.charAt(i) == '-')) {   // 2. an optional sign
        if (s.charAt(i) == '-') sign = -1;
        i++;
    }
    long value = 0;                              // 64 bits: room to go past 2^31
    while (i < n && Character.isDigit(s.charAt(i))) {   // 3. digits, until anything else
        value = value * 10 + (s.charAt(i) - '0');
        if (value > (long) Integer.MAX_VALUE + 1) break;   // already too big: stop reading
        i++;
    }
    value *= sign;
    return (int) Math.max(Integer.MIN_VALUE, Math.min(Integer.MAX_VALUE, value));   // 4. clamp
}

